-- Keybinds
hl.unbind("SUPER + Return")
hl.bind("SUPER + Return", hl.dsp.exec_cmd("kitty"))
hl.unbind("SUPER + E")
hl.bind("SUPER + SHIFT + F", hl.dsp.exec_cmd("nautilus"))
hl.unbind("SUPER + R")
hl.bind("SUPER + space", hl.dsp.exec_raw("~/.config/rofi/scripts/launcher.sh"))
hl.unbind("SUPER + C")
hl.bind("SUPER + W", hl.dsp.window.close())
hl.unbind("SUPER + V")
hl.bind("SUPER + T", hl.dsp.window.float({ action = "toggle" }))
hl.unbind("SUPER + SHIFT + B")
hl.bind("SUPER + SHIFT + B", hl.dsp.exec_cmd("helium-browser"))
hl.unbind("SUPER + CTRL + space")
hl.bind("SUPER + CTRL + space", hl.dsp.exec_raw("~/.local/bin/wallpaper-select"))
hl.unbind("SUPER + Q")
hl.bind("SUPER + Q", hl.dsp.exec_raw("kitty -e wiremix"))
hl.unbind("SUPER + SHIFT + space")
hl.bind("SUPER + SHIFT + space", hl.dsp.exec_cmd("pgrep -x waybar > /dev/null && pkill -x waybar || waybar"))
hl.unbind("SUPER + CTRL + E")
hl.bind("SUPER + CTRL + E", hl.dsp.exec_cmd("rofi -show emoji -theme ~/.config/rofi/catppuccin-mocha.rasi -modi emoji -emoji-format \"{emoji} {name}\""))
hl.unbind("SUPER + SHIFT + Right")
hl.bind("SUPER + SHIFT + Right", hl.dsp.window.move({ direction = "right" }))
hl.unbind("SUPER + SHIFT + Up")
hl.bind("SUPER + SHIFT + Up", hl.dsp.window.move({ direction = "up" }))
hl.unbind("SUPER + SHIFT + Down")
hl.bind("SUPER + SHIFT + Down", hl.dsp.window.move({ direction = "down" }))
hl.unbind("SUPER + SHIFT + Left")
hl.bind("SUPER + SHIFT + Left", hl.dsp.window.move({ direction = "left" }))
hl.unbind("SUPER + I")
hl.bind("SUPER + I", hl.dsp.exec_raw("~/.config/rofi/scripts/pacman-installer.sh"))

-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("exec-once = ~/.local/bin/wallpaper-restore")
    hl.exec_cmd("waybar &")
end)
